from pathlib import Path
import json,shutil,subprocess,hashlib,concurrent.futures,html
W=Path('work/cpu-soak');O=Path('outputs/prueba-cpu-original-vs-mod');O.mkdir(exist_ok=True)
for d in ['Combates','Original','Mod','Capturas']: (O/d).mkdir(exist_ok=True)
pairs=[(0,1),(9,6),(10,8),(2,5),(3,4),(7,5)]
names=['Goku SSJ','Gohan SSJ2','Piccolo','Vegeta SSJ','Trunks SSJ','Cell','A18','Krilin','Freezer','Recoome','Ginyu']
