def package(index):
 reports={v:json.loads((W/'results'/v/f'{index:02}'/'Informe.json').read_text(encoding='utf-8')) for v in hashes}
 a,b=pairs[index];label=names[a]+' vs '+names[b];filename=f'{index+1:02}-'+label.replace(' ','-')+'.mp4';e=dict(index=index,pair=[a,b],label=label,comparison='Combates/'+filename)
 for v,d in reports.items():
  assert d['source_rom_sha256']==hashes[v] and d['pair']==[a,b] and d['host_combat_buttons']==[] and d['freeze_suspect'] is None
  src=W/'results'/v/f'{index:02}'/'CPU.mp4';assert sha(src)==d['video_sha256']
  folder='Original' if v=='original' else 'Mod';shutil.copyfile(src,O/folder/filename)
  for shot in ['Inicio','Final']:shutil.copyfile(src.parent/(shot+'.png'),O/'Capturas'/f'{index:02}-{v}-{shot}.png')
  e[v]=dict(seconds=d['gameplay_seconds'],frames=d['frames'],initial_hp=[d['initial'][p]['hp'] for p in ['p1','p2']],final_hp=[d['final'][p]['hp'] for p in ['p1','p2']],freeze_suspect=d['freeze_suspect'],host_buttons=d['host_combat_buttons'],video=f'{folder}/{filename}',video_sha256=d['video_sha256'],native_ko=d['native_ko_frame'],samples=len(d['samples']),atlas_judged=sum(s.get('atlas_judged',False) for s in d['samples']),atlas_faults=sum(s.get('atlas_fault',False) for s in d['samples']))
 vf=f"[0:v]fps=60,setpts=PTS-STARTPTS[a];[1:v]fps=60,setpts=PTS-STARTPTS[b];[a][b]hstack=inputs=2:shortest=1,pad=iw:ih+56:0:56:color=0x101723,drawtext=fontfile={font}:text='ROM ORIGINAL - CPU vs CPU':x=18:y=9:fontsize=22:fontcolor=white,drawtext=fontfile={font}:text='ROM NUEVA v4 - CPU vs CPU':x=658:y=9:fontsize=22:fontcolor=white,drawtext=fontfile={font}:text='{label} - misma seleccion y opciones - sin botones humanos':x=18:y=35:fontsize=15:fontcolor=0xb5c1d2"
 ff(['-i',str(O/'Original'/filename),'-i',str(O/'Mod'/filename),'-filter_complex',vf,'-an','-c:v','libx264','-preset','fast','-crf','18','-pix_fmt','yuv420p','-movflags','+faststart',str(O/e['comparison'])])
 e['comparison_sha256']=sha(O/e['comparison']);print('Packaged CPU comparison',label,flush=True);return e
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:entries=list(pool.map(package,range(6)))
listing=W/'comparison-concat.txt';listing.write_text(''.join("file '"+str((O/e['comparison']).resolve()).replace('\\','/')+"'\n" for e in entries),encoding='utf-8')
montage='Comparacion-CPU-original-vs-mod.mp4';ff(['-f','concat','-safe','0','-i',str(listing),'-c','copy','-movflags','+faststart',str(O/montage)])
candidate=Path('repository/dist/Jugabilidad_v1_Colores_v1_Ki_Individual_v4.bin');assert sha(candidate)==hashes['enhanced']
romName='Buyuu_Retsuden_Enhanced_v4_Prueba_CPU.bin';shutil.copyfile(candidate,O/romName);shutil.copyfile('repository/patches/auras-c2-v4/auras-c2.ips',O/'Buyuu_Retsuden_Enhanced_v4.ips')
audit=json.loads((W/'comparison-audit.json').read_text(encoding='utf-8'))
assert all(v<=300 for v in audit['total_including_known_preflights'].values())
summary=dict(date='2026-11-04',status='PASS for this bounded native CPU comparison; not human-playability approval or exhaustive special-attack validation',source_hashes=hashes,rom_filename=romName,rom_bytes=(O/romName).stat().st_size,rom_sha256=sha(O/romName),patch_sha256=sha(O/'Buyuu_Retsuden_Enhanced_v4.ips'),pairs=entries,formal_gameplay_seconds={v:sum(e[v]['seconds'] for e in entries) for v in hashes},total_gameplay_seconds_including_preflights=audit['total_including_known_preflights'],max_seconds_per_rom=300,video=montage,video_sha256=sha(O/montage),method=['Each ROM boots independently with the same native menu navigation, matchup, stage and default options.','Original is the untouched Japanese ROM217fc312, not the previously recolored6460comparison source.','Only native control-type bytes P1+BE/P2+BE are enabled for CPU. No host button, health, position, RNG or scene forcing during combat.','Native normal speed retained. Six formal bouts of at most35seconds cover the11fighters on tournament stage0. Each video starts after CPU activation.','Combat traces diverge; damage/winners are not a deterministic balancing or responsiveness test.'],findings=['No five-second identical-frame/counter freeze suspects detected in the12formal bouts.','Both native AIs act and deal damage. No KO occurred inside these bounded clips.','Twenty sampled visible-Ki states in Krilin/Cell have correct resident graphics. Other residency samples do not imply visible Ki coverage.','No cinematic special-effect state was triggered; real end-of-special restoration was not validated by this autoplay.','Conservative scanline-width pressure exceeds320 in some Piccolo/Cell frames in both original and mod; inspected stills do not show an obvious new visual defect.'],limits=['One stage, normal speed, native default difficulty; no turbo or physical-console coverage.','Graphics/AI snapshots sampled every6frames plus events; not a per-frame hardware or controller-latency proof.','Human feel, command responsiveness and SF2CE-like playability remain for the user to assess with a controller.','Current ROM includes gameplayv1, colorsv1 and individualKiv4. TitleG, real-namecredit, selectedportraits, HUDH4 and snowstage are not yet integrated.','Videos are muted.'])
(O/'Informe-comparativo.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');shutil.copyfile(W/'comparison-audit.json',O/'Auditoria-detallada.json')
cards=[]
for e in entries:
 old='/'.join(str(x) for x in e['original']['final_hp']);new='/'.join(str(x) for x in e['enhanced']['final_hp'])
 cards.append(f'''<article><h2>{html.escape(e['label'])}</h2><video controls preload="none" poster="Capturas/{e['index']:02}-enhanced-Final.png" src="{e['comparison']}"></video><p>Vida final P1/P2: original {old}; nueva {new}. Las decisiones de IA pueden divergir.</p><p><a href="{e['original']['video']}">Sólo original</a> · <a href="{e['enhanced']['video']}">Sólo nueva</a></p></article>''')
page='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CPU · original frente al mod</title><style>body{margin:0;background:#101723;color:#eaf1fc;font:17px/1.5 system-ui}main{max-width:1400px;margin:auto;padding:28px}h1{font-size:30px}p{max-width:1000px}video{display:block;width:100%;background:#060a10;border-radius:8px}a{color:#9edaff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(480px,1fr));gap:24px}article{background:#1c2738;padding:20px;border-radius:12px}article h2{margin-top:0}.note{border-left:4px solid #f6ce60;padding:14px 18px;background:#263043}.links{margin:16px 0 28px}@media(max-width:550px){main{padding:14px}.grid{grid-template-columns:1fr}article{padding:12px}}</style><main><h1>CPU contra CPU: original frente al mod</h1><p>Seis combates de 35 segundos por versión, con los once personajes. ROM japonesa original sin parches a la izquierda y nuestra v4 a la derecha. La IA nativa controla a ambos jugadores; ningún botón humano durante el combate.</p><p class="note"><strong>Sin bloqueos detectados en esta prueba.</strong> Esto comprueba estabilidad y comportamiento observado; la sensación del mando queda para tu prueba. No se activaron escenas especiales, por lo que no se valida aquí su retirada gráfica.</p><video controls preload="metadata" src="Comparacion-CPU-original-vs-mod.mp4"></video><p class="links"><a href="Buyuu_Retsuden_Enhanced_v4_Prueba_CPU.bin">Descargar ROM de prueba</a> · <a href="Buyuu_Retsuden_Enhanced_v4.ips">Parche IPS para la original japonesa</a> · <a href="Informe-comparativo.json">Informe y hashes</a></p><section class="grid">'''+''.join(cards)+'''</section><p>La ROM combina jugabilidad v1, paletas v1 y ki individual v4. La presentación, el crédito, los retratos de selección, el HUD H4 y el escenario nevado siguen pendientes de integrar. Prueba en emulador, velocidad normal, escenario del torneo. Vídeos sin audio.</p></main></html>'''
